/* Raya System "Terminal" (terminal) — generated by Export, do not edit by hand */

[data-raya="terminal"] {
  --raya-accent-1: oklch(0.96 0.0952 150);
  --raya-accent-2: oklch(0.895 0.1083 150);
  --raya-accent-3: oklch(0.829 0.1214 150);
  --raya-accent-4: oklch(0.764 0.1345 150);
  --raya-accent-5: oklch(0.698 0.1476 150);
  --raya-accent-6: oklch(0.633 0.1593 150);
  --raya-accent-7: oklch(0.567 0.1463 150);
  --raya-accent-8: oklch(0.502 0.1332 150);
  --raya-accent-9: oklch(0.436 0.1201 150);
  --raya-accent-10: oklch(0.371 0.107 150);
  --raya-accent-11: oklch(0.305 0.0939 150);
  --raya-accent-12: oklch(0.24 0.0808 150);
  --background: oklch(0.97 0.005 150);
  --foreground: oklch(0.18 0.01 150);
  --card: oklch(0.99 0.003 150);
  --card-foreground: oklch(0.18 0.01 150);
  --popover: oklch(0.99 0.003 150);
  --popover-foreground: oklch(0.18 0.01 150);
  --primary: var(--raya-accent-8);
  --primary-foreground: oklch(0.98 0.003 150);
  --secondary: var(--raya-accent-2);
  --secondary-foreground: oklch(0.25 0.02 150);
  --muted: var(--raya-accent-2);
  --muted-foreground: oklch(0.45 0.03 150);
  --accent: var(--raya-accent-3);
  --accent-foreground: oklch(0.22 0.02 150);
  --destructive: oklch(0.55 0.22 29);
  --border: var(--raya-accent-6);
  --input: var(--raya-accent-6);
  --ring: var(--raya-accent-8);
  --chart-1: var(--raya-accent-8);
  --chart-2: var(--raya-accent-10);
  --chart-3: var(--raya-accent-6);
  --chart-4: oklch(0.55 0.22 29);
  --chart-5: var(--raya-accent-4);
  --sidebar: var(--raya-accent-2);
  --sidebar-foreground: oklch(0.2 0.01 150);
  --sidebar-primary: var(--raya-accent-8);
  --sidebar-primary-foreground: oklch(0.98 0.003 150);
  --sidebar-accent: var(--raya-accent-4);
  --sidebar-accent-foreground: oklch(0.24 0.02 150);
  --sidebar-border: var(--raya-accent-6);
  --sidebar-ring: var(--raya-accent-8);
  --font-sans: JetBrains Mono, ui-monospace, monospace;
  --font-mono: JetBrains Mono, ui-monospace, monospace;
  --radius: 0rem;
  --raya-button-bg: var(--background);
  --raya-button-fg: var(--foreground);
  --raya-button-border: var(--border);
  --raya-button-height: 2rem;
  --raya-button-px: 0.75rem;
  --raya-button-font-size: 0.8125rem;
  --raya-card-padding: 0.875rem;
  --raya-card-gap: 0.5rem;
  --raya-badge-px: 0.5rem;
  --raya-badge-py: 0.125rem;
  --raya-badge-font-size: 0.6875rem;
  --raya-avatar-size: 1.5rem;
  --raya-avatar-radius: 0px;
}

