}

{
  "slug": "terminal",
  "name": "Terminal",
  "description": "Monospaced, square-cornered, phosphor green on near-black.",
  "isDefault": false,
  "fonts": {
    "sans": [
      "JetBrains Mono",
      "ui-monospace",
      "monospace"
    ],
    "mono": [
      "JetBrains Mono",
      "ui-monospace",
      "monospace"
    ]
  },
  "radius": "0rem",
  "ramp": {
    "names": "--raya-accent-1..12",
    "steps": 12
  },
  "knobs": {
    "button": {
      "variant": "outline",
      "size": "sm"
    },
    "card": {
      "density": "compact"
    },
    "badge": {
      "size": "sm"
    },
    "avatar": {
      "shape": "square",
      "size": "sm"
    }
  },
  "stylesheet": "src/styles/raya/systems/terminal.css"
}

docs:
Add to src/styles.css:

@import "./styles/raya/core.css";
@import "./styles/raya/systems/terminal.css";

The default System also fills :root/.dark; other Systems activate via <html data-raya="terminal">.
